"""The supplied execution gate. Students do not edit this file.

The gate never consults the student's projection, the agent context, or the
evidence IDs a planner cites. It reads the authoritative event table directly
with SQL and checks the proposal's exact commit and environment.

Policy (event evt-001): deploy only a commit whose required test suite
passed, with an explicit approval for that exact commit and environment.
"Finish the deployment" resumes the task; it is not an approval.
"""

from __future__ import annotations

from .models import (
    APPROVAL_MISSING,
    HEAD_UNKNOWN,
    REQUIRED_SUITE,
    TESTS_FAILED,
    TESTS_UNKNOWN,
    AuthoritativeFacts,
    GateResult,
    Proposal,
)
from .store import EventStore

COMMIT_NOT_CURRENT = "commit_not_current_head"
ENVIRONMENT_NOT_REQUESTED = "environment_not_requested_target"
ALL_CHECKS_PASSED = "all_checks_passed"
NO_SIDE_EFFECT = "no_side_effect"

_HEAD_SQL = """
SELECT event_id, json_extract(body, '$.payload.commit') AS commit_id
FROM events
WHERE session_id = ? AND type = 'head.changed'
ORDER BY sequence DESC LIMIT 1
"""

# Highest completed run number wins; sequence breaks ties.
_TEST_SQL = """
SELECT event_id,
       json_extract(body, '$.payload.result')     AS result,
       json_extract(body, '$.payload.run_number') AS run_number
FROM events
WHERE session_id = ? AND type = 'test.completed'
  AND json_extract(body, '$.payload.commit') = ?
  AND json_extract(body, '$.payload.suite') = ?
ORDER BY run_number DESC, sequence DESC LIMIT 1
"""

_APPROVAL_SQL = """
SELECT event_id, json_extract(body, '$.payload.approval_id') AS approval_id
FROM events
WHERE session_id = ? AND type = 'approval.granted'
  AND json_extract(body, '$.payload.commit') = ?
  AND json_extract(body, '$.payload.environment') = ?
ORDER BY sequence DESC LIMIT 1
"""


def authoritative_facts(store: EventStore, session_id: str, commit: str | None, environment: str) -> AuthoritativeFacts:
    through = store.last_sequence(session_id)
    head = store.query(_HEAD_SQL, (session_id,))
    test = store.query(_TEST_SQL, (session_id, commit, REQUIRED_SUITE)) if commit else []
    approval = store.query(_APPROVAL_SQL, (session_id, commit, environment)) if commit else []
    return AuthoritativeFacts(
        checked_through_sequence=through,
        head_commit=head[0]["commit_id"] if head else None,
        head_source_event_id=head[0]["event_id"] if head else None,
        test_result=test[0]["result"] if test else "unknown",
        test_run_number=test[0]["run_number"] if test else None,
        test_source_event_id=test[0]["event_id"] if test else None,
        approval_id=approval[0]["approval_id"] if approval else None,
        approval_source_event_id=approval[0]["event_id"] if approval else None,
    )


def validate(store: EventStore, session_id: str, proposal: Proposal, requested_environment: str) -> GateResult:
    """Check a proposal against authoritative state before any side effect."""
    facts = authoritative_facts(store, session_id, proposal.commit, proposal.environment)

    blockers: list[str] = []
    if facts.head_commit is None:
        blockers.append(HEAD_UNKNOWN)
    elif proposal.commit != facts.head_commit:
        blockers.append(COMMIT_NOT_CURRENT)
    if proposal.environment != requested_environment:
        blockers.append(ENVIRONMENT_NOT_REQUESTED)
    if facts.test_result == "failed":
        blockers.append(TESTS_FAILED)
    elif facts.test_result == "unknown":
        blockers.append(TESTS_UNKNOWN)
    if facts.approval_id is None:
        blockers.append(APPROVAL_MISSING)

    if proposal.action != "deploy":
        outcome, reasons = "allowed", [NO_SIDE_EFFECT]
    elif blockers:
        outcome, reasons = "blocked", list(blockers)
    else:
        outcome, reasons = "allowed", [ALL_CHECKS_PASSED]

    return GateResult(
        action=proposal.action,
        commit=proposal.commit,
        environment=proposal.environment,
        outcome=outcome,
        reason_codes=reasons,
        authoritative_blockers=blockers,
        authoritative=facts,
    )
